-- Run after events-hub.sql in the same isolated review database.
-- Existing form/booking IDs and URLs are retained. ON CONFLICT prevents repeated imports.
begin;
with source as (
 select f.*,f.configuration c from public.icsh_forms f where kind='tickets' and status='published' and mode='live' and not coalesce((configuration->>'prototype')::boolean,false)
), content as (
 select *,jsonb_build_object('title',c->>'title','description',c->>'description','startsAt',c->>'startsAt','endsAt',c->>'endsAt','venue',c->>'venue','address','','image','',
 'childTickets',c->'rates' ? 'child','bookingType',case when coalesce((c->'rates'->>'nonmember')::integer,0)=0 and coalesce((c->'rates'->>'member')::integer,0)=0 then 'free' else 'paid' end,'externalUrl','',
 'capacity',c->'capacity','bookingOpens',c->'bookingOpens','bookingCloses',c->'bookingCloses','bookingEnabled',true,
 'prices',jsonb_build_object('member',coalesce((c->'rates'->>'member')::integer,0),'nonmember',coalesce((c->'rates'->>'nonmember')::integer,0),'child',coalesce((c->'rates'->>'child')::integer,0),'childNonmember',coalesce((c->'rates'->>'childNonmember')::integer,(c->'rates'->>'child')::integer,0),'under5',0),'instructions',coalesce(c->>'eventTerms','')) body from source
)
insert into public.icsh_events(slug,source_type,source_key,form_ids,draft,published,status,visible) select slug,'tickets',id::text,array[id],body,body,'published',true from content on conflict do nothing;
with festival as (
 select *,configuration c from public.icsh_forms where kind='participation' and status='published' and mode='live'
), content as (
 select *,jsonb_build_object('title',c->>'eventName','description',coalesce(c->>'introduction','A community fundraising event supporting UK charities and ICSH community projects.'),'startsAt',c->>'startsAt','endsAt',c->>'endsAt','venue',c->>'venue','address','','image','',
 'childTickets',false,'bookingType','information','externalUrl','','capacity',null,'bookingOpens',null,'bookingCloses',null,'bookingEnabled',true,
 'prices',jsonb_build_object('member',0,'nonmember',0,'child',0,'childNonmember',0,'under5',0),'instructions','') body from festival
)
insert into public.icsh_events(slug,source_type,source_key,form_ids,draft,published,status,visible)
 select slug,'festival',id::text,array(select f.id from public.icsh_forms f where f.mode='live' and f.kind in ('participation','stall') and f.configuration->>'eventName'=c->>'eventName' and f.configuration->>'startsAt'=c->>'startsAt'),body,body,'published',true from content on conflict do nothing;
with source as (select *,configuration c from public.icsh_iftari_settings), content as (
 select *,jsonb_build_object('title',c->>'title','description','Join ICSH members, families and friends for an evening of food, friendship and community.',
 'startsAt',to_char((((c->>'date')::date+coalesce((c->>'time')::time,'16:45'::time)) at time zone 'Europe/London') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
 'endsAt',to_char(((((c->>'date')::date+coalesce((c->>'time')::time,'16:45'::time)) at time zone 'Europe/London')+interval '3 hours') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
 'venue',c->>'venue','address','','image','','childTickets',true,'bookingType','paid','externalUrl','','capacity',coalesce(c->'capacity','null'::jsonb),'bookingOpens',null,'bookingCloses',null,'bookingEnabled',c->>'status'='published',
 'prices',(c->'prices')||jsonb_build_object('childNonmember',c->'prices'->'child','under5',coalesce(nullif(c->'prices'->'under5','null'::jsonb),'0'::jsonb)),'instructions','') body from source where c->>'date' is not null
)
-- Preserve the existing public Iftari teaser even though its bookings are still draft.
insert into public.icsh_events(slug,source_type,source_key,draft,published,status,visible) select slug,'iftari',slug,body,body,'published',true from content on conflict do nothing;
